// 대시보드 «지금 값 불러오기» 버튼이 부르는 계산.
// 페이퍼 트레이딩 봇의 «손익 계산» 노드와 같은 방식으로 재야 Discord 알림 숫자와 맞는다:
//   - 청산가는 마지막 체결가가 아니라 실제 팔리는 값(최우선 매수호가)을 쓴다
//   - 손익은 두 다리를 따로 재서 더한다 (2026-09-28 변경, 봇과 동시에 바꿈)
//       q    = 투입금 × 진입환율 / 진입 국내가
//       코빗 = q × 매수호가 / 지금환율 − 투입금
//       OKX  = q × (진입 해외가 − 지금 해외가)
//     진입 해외가가 없는 옛 포지션만 예전 공식 «(청산김프 − 진입김프) × 투입금».
//   - 대시보드 «거래소별 잔액»이 쓸 수 있게 bid·foreignPrice 원값도 함께 돌려준다
const FEE_RATE = 0.0002;   // 편도. 국내 0%(코빗 무료) + 해외 지정가 0.02%
const MAX_POSITIONS = 4;   // 봇의 «진입 가능 여부 판단» 노드와 같아야 한다
const SPARK_POINTS = 40;   // 스파크라인 최대 점 개수. 64px 폭에는 이 정도면 충분하다

const r2 = function (v) { return Math.round(v * 100) / 100; };
const r4 = function (v) { return Math.round(v * 10000) / 10000; };

const positions = $('보유 포지션 조회').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.coin && r.status === 'OPEN'; });

// 호가 응답은 포지션과 1:1, 같은 순서로 돌아온다. 개수가 어긋나면 짝을 믿지 않는다.
const books = $('코빗 호가 조회').all().map(function (i) { return i.json; });
const aligned = books.length === positions.length;

// 김프 이력은 종목별로 섞여 들어온다. coin 컬럼이 있어서 다시 묶을 수 있다.
const hist = {};
$input.all().forEach(function (i) {
  const r = i.json;
  if (!r || !r.coin || r.premium === undefined || r.premium === null || !r.checkedAt) return;
  const t = new Date(r.checkedAt).getTime();
  if (!isFinite(t)) return;
  if (!hist[r.coin]) hist[r.coin] = [];
  hist[r.coin].push({ t: t, p: Number(r.premium), k: Number(r.korbitPrice), f: Number(r.foreignPrice), fx: Number(r.usdKrwRate) });
});
Object.keys(hist).forEach(function (c) {
  hist[c].sort(function (a, b) { return a.t - b.t; });
});

const fxBody = $('환율 조회').first().json;
const fx = (fxBody && fxBody.rates && fxBody.rates.KRW) ? Number(fxBody.rates.KRW) : null;

const okxBody = $('OKX 가격 조회').first().json;
const okxRows = (okxBody && okxBody.data) ? okxBody.data : [];
const foreign = {};
okxRows.forEach(function (r) { foreign[String(r.instId)] = Number(r.last); });

const rows = [];
let totalUnrealized = 0;
let priced = 0;

positions.forEach(function (p, idx) {
  const bookJson = aligned ? (books[idx] || {}) : {};
  const ob = bookJson.data || {};
  const bids = ob.bids || [];
  const fp = foreign[p.coin + '-USDT-SWAP'];

  const size = Number(p.positionSize);
  const entryPremium = Number(p.entryPremium);
  const entryPrice = Number(p.entryPrice);
  const entryFp = Number(p.entryForeignPrice);
  const entryFx = Number(p.entryFx) || (entryFp > 0 ? entryPrice / (entryFp * (1 + entryPremium / 100)) : 0);
  const q = (entryFp > 0 && entryFx > 0 && entryPrice > 0) ? size * entryFx / entryPrice : null;
  const feeEntry = Number(p.feeEntry || 0);
  const feeExit = size * FEE_RATE;

  // 어느 시점의 값(국내가·해외가·환율, 또는 김프만)으로 청산했을 때의 순손익
  const pnlAt = function (k, f, x, prem) {
    if (q !== null && k > 0 && f > 0 && x > 0) {
      return r2(q * k / x - size + q * (entryFp - f) - feeEntry - feeExit);
    }
    return r2(size * (prem - entryPremium) / 100 - feeEntry - feeExit);
  };

  let currentPremium = null;
  let netProfit = null;
  let bid = null;
  let note = null;

  if (!fx) {
    note = '환율 없음';
  } else if (!fp) {
    note = '해외가 없음';
  } else if (!bids.length || !Number(bids[0].price)) {
    note = '호가 없음';
  } else {
    bid = Number(bids[0].price);
    currentPremium = r4(((bid / fx / fp) - 1) * 100);
    netProfit = pnlAt(bid, fp, fx, currentPremium);
    totalUnrealized += netProfit;
    priced++;
  }

  // --- 진입 이후 평가손익 추이 ---
  // 이력은 체결가 기준이라 마지막 점은 버리고, 실제 매도호가로 계산한
  // 현재값을 붙인다. 그래야 선 끝이 표에 적힌 숫자와 맞는다.
  const entryTs = new Date(p.entryTime).getTime();
  const all = hist[p.coin] || [];
  const since = all.filter(function (x) { return x.t >= entryTs; });
  const pt = function (x) { return pnlAt(x.k, x.f, x.fx, x.p); };

  let spark = [];
  if (since.length) {
    if (since.length <= SPARK_POINTS) {
      spark = since.map(pt);
    } else {
      // 균등 간격으로 골라내되 처음과 끝은 항상 포함한다
      const stepN = (since.length - 1) / (SPARK_POINTS - 1);
      for (let k = 0; k < SPARK_POINTS; k++) {
        spark.push(pt(since[Math.round(k * stepN)]));
      }
    }
    if (netProfit !== null) spark[spark.length - 1] = netProfit;
  } else if (netProfit !== null) {
    spark = [netProfit];
  }

  rows.push({
    coin: p.coin,
    entryPremium: r4(entryPremium),
    currentPremium: currentPremium,
    netProfit: netProfit,
    entryTime: p.entryTime,
    heldMinutes: Math.round((Date.now() - entryTs) / 60000),
    note: note,
    bid: bid,
    foreignPrice: fp || null,
    spark: spark,
    sparkFrom: since.length ? new Date(since[0].t).toISOString() : null,
    sparkPoints: spark.length
  });
});

// 평가손익이 큰 쪽부터 위로
rows.sort(function (a, b) {
  if (a.netProfit === null) return 1;
  if (b.netProfit === null) return -1;
  return b.netProfit - a.netProfit;
});

return [{ json: {
  ok: true,
  checkedAt: new Date().toISOString(),
  usdKrw: fx,
  maxPositions: MAX_POSITIONS,
  openCount: positions.length,
  pricedCount: priced,
  totalUnrealized: r2(totalUnrealized),
  positions: rows
} }];

